local Window = getgenv().SORU_Window
if not Window then return end

-- ============ SERVICES, TANPA WaitForChild ============
local Players = game:GetService("Players")
local PPS = game:GetService("ProximityPromptService")
local VIM = game:GetService("VirtualInputManager")
local RS = game:GetService("ReplicatedStorage")
local RunService = game:GetService("RunService")
local TweenService = game:GetService("TweenService")
local plr = Players.LocalPlayer

-- ============ DATA PENTING, JANGAN UBAH ============
local SAFE_BASE_POS = Vector3.new(-13.8073769, 4.5, -53.5250626)
local SAFE_BASE_CF = CFrame.new(-13.8073769, 4.5, -53.5250626, 0, 0, 1, 0, 1, -0, -1, 0, 0)
local SAFE_BASE_MID = Vector3.new(-75, 3.5, -7.4)
local HELPER_DROP_POS = Vector3.new(-105.2, 3.7, -6.2)
local OFFSET_DIST = 3
local RANGE = 15
local SLIDER_MIN, SLIDER_MAX = 16, 500
local sliderSpeed = 16

-- ============ FALLBACK LIB LAMA / BARU ============
local function grp(title, icon)
    if Window.Group then return Window:Group({ Title = title, Icon = icon }) end
    if Window.CreateGroup then return Window:CreateGroup({ Title = title, Icon = icon }) end
    return nil
end
local function tabOf(g, o)
    if g and g.Tab then return g:Tab(o) end
    if g and g.CreateTab then return g:CreateTab(o) end
    if Window.CreateTab then return Window:CreateTab(o) end
    if Window.Tab then return Window:Tab(o) end
    return nil
end
local function accOf(page, o)
    if page.Accordion then return page:Accordion(o) end
    if page.Card then return page:Card(o) end
    if page.Group then return page:Group(o) end
    if page.CreateSection then return page:CreateSection(o) end
    return page
end
local function comp(parent, names, o)
    for _, n in ipairs(names) do
        if parent[n] then return parent[n](parent, o) end
    end
    return nil
end
local function tog(p, o) return comp(p, { "Toggle", "CreateToggle" }, o) end
local function sld(p, o) return comp(p, { "Slider", "CreateSlider" }, o) end
local function drp(p, o) return comp(p, { "Dropdown", "CreateDropdown" }, o) end
local function mdrp(p, o) return comp(p, { "MultiDropdown", "CreateMultiDropdown", "Dropdown" }, o) end
local function btn(p, o) return comp(p, { "Button", "CreateButton" }, o) end
local function lbl(p, o) return comp(p, { "Label", "CreateLabel", "Paragraph" }, o) end
local function inf(p, o) return comp(p, { "Info", "Label" }, o) end
local function para(p, o) return comp(p, { "Paragraph", "Label", "CreateLabel" }, o) end
local function panelOf(o)
    if Window.Panel then return Window:Panel(o) end
    if Window.CreatePanel then return Window:CreatePanel(o) end
    return tabOf(nil, { Title = o.Title or "Tracker", Icon = "eye" })
end

-- ============ HELPER SATUIN: posOf / tpTo / namesFrom ============
local function posOf(m)
    if not m then return nil end
    if m:IsA("BasePart") then return m.Position end
    if m:IsA("Model") then
        if m.PrimaryPart then return m.PrimaryPart.Position end
        local ok, cf = pcall(function() return m:GetPivot() end)
        if ok and cf then return Vector3.new(cf.X, cf.Y, cf.Z) end
        for _, v in ipairs(m:GetDescendants()) do if v:IsA("BasePart") then return v.Position end end
        return nil
    end
    local ok, cf = pcall(function() return m:GetPivot() end)
    if ok and cf then return Vector3.new(cf.X, cf.Y, cf.Z) end
    if m.FindFirstChildWhichIsA then local bp = m:FindFirstChildWhichIsA("BasePart", true) if bp then return bp.Position end end
    return nil
end
local function offsetPosOf(m)
    local base = posOf(m)
    if not base then return nil, nil end
    local hrp = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart")
    local dir = hrp and Vector3.new(hrp.Position.X - base.X, 0, hrp.Position.Z - base.Z) or Vector3.new(0, 0, 1)
    if dir.Magnitude < 1 then dir = Vector3.new(0, 0, 1) end
    return Vector3.new(base.X, 3.5, base.Z) + dir.Unit * OFFSET_DIST, Vector3.new(base.X, 3.5, base.Z)
end
local function tpTo(target, keepRot)
    local hrp = plr.Character and plr.Character:FindFirstChild("HumanoidRootPart")
    if not hrp then return end
    local pos = nil
    if typeof(target) == "Vector3" then pos = target
    elseif typeof(target) == "CFrame" then hrp.CFrame = target return
    else pos = posOf(target) end
    if not pos then return end
    if keepRot then hrp.CFrame = CFrame.new(pos) * (hrp.CFrame - hrp.CFrame.Position) else hrp.CFrame = CFrame.new(pos) end
end
local function namesFrom(folder)
    local out = {}
    if folder then for _, m in ipairs(folder:GetChildren()) do if m:IsA("Model") then table.insert(out, m.Name) end end end
    if #out == 0 then out = { "Zone1" } end
    return out
end
local function zoneFolder()
    local b = workspace:FindFirstChild("Build")
    if b then local zb = b:FindFirstChild("ZoneBuilds") if zb then return zb end end
    return workspace:FindFirstChild("ZoneBuilds") or workspace:FindFirstChild("Build")
end
local function zoneOf(model)
    local pos = posOf(model)
    if not pos then return "Unknown" end
    local zb = zoneFolder()
    if not zb then return "Unknown" end
    local best, md = "Unknown", math.huge
    for _, z in ipairs(zb:GetChildren()) do
        if z:IsA("Model") then local zp = posOf(z) if zp then local d = (Vector3.new(pos.X, 0, pos.Z) - Vector3.new(zp.X, 0, zp.Z)).Magnitude if d < md then md = d best = z.Name end end end
    end
    return best
end
local function cashTxt(m)
    for _, v in ipairs(m:GetDescendants()) do if v.Name == "CashPerSecond" and v:IsA("TextLabel") then return v.Text end end
    return "?"
end
local function parseCash(t)
    if not t then return 0 end
    local s = tostring(t):gsub("%$", ""):gsub("/s", ""):gsub("/sec", ""):gsub(" ", ""):gsub(",", ""):upper()
    local n = tonumber(s:match("[%d%.]+"))
    if not n then return 0 end
    if s:find("K") then n *= 1000 elseif s:find("M") then n *= 1000000 elseif s:find("B") then n *= 1000000000 elseif s:find("T") then n *= 1000000000000 end
    return n
end
local function unwrap(v) if type(v) == "table" then return v[1] end return v end
local function findHumanoid(char) return char and char:FindFirstChildOfClass("Humanoid") or nil end
local function findHRP(char) return char and char:FindFirstChild("HumanoidRootPart") or nil end

