    return nil
end
local function isDropVisible()
    local b = findDropButton()
    if not b or not b.Visible then return false end
    local cur = b.Parent
    while cur and cur ~= plr.PlayerGui do if cur:IsA("GuiObject") and not cur.Visible then return false end cur = cur.Parent end
