    if not folder then return nil end
    local best, md = nil, maxDist or 8
    for _, m in ipairs(folder:GetChildren()) do
        if m:IsA("Model") then local p = posOf(m) if p then local d = (Vector3.new(hrp.Position.X, 0, hrp.Position.Z) - Vector3.new(p.X, 0, p.Z)).Magnitude if d < md then md = d best = m end end end
    end
