-- ============ WALK ============
local function walkDirect(targetPos, lookAt, keepRot)
    local hrp = findHRP(plr.Character)
    if not hrp or not targetPos then return end
    if lookAt then lookAt = Vector3.new(lookAt.X, targetPos.Y, lookAt.Z) end
    pcall(function() hrp.AssemblyLinearVelocity = Vector3.zero hrp.AssemblyAngularVelocity = Vector3.zero end)
    local function distLeft() return (Vector3.new(hrp.Position.X, 0, hrp.Position.Z) - Vector3.new(targetPos.X, 0, targetPos.Z)).Magnitude end
    if distLeft() < 1.2 then return end
    while distLeft() > 1.2 do
        if not plr.Character or not hrp.Parent then break end
        local cur = Vector3.new(hrp.Position.X, targetPos.Y, hrp.Position.Z)
        local dir = Vector3.new(targetPos.X - cur.X, 0, targetPos.Z - cur.Z)
        if dir.Magnitude < 0.1 then break end
        dir = dir.Unit
        local dt = RunService.Heartbeat:Wait()
        local step = dir * getWalkSpeed() * dt
        if step.Magnitude > distLeft() then step = dir * distLeft() end
        local newPos = cur + step
        local cf = keepRot and CFrame.new(newPos) * (hrp.CFrame - hrp.CFrame.Position) or (lookAt and CFrame.lookAt(newPos, lookAt) or CFrame.lookAt(newPos, newPos + dir))
        hrp.CFrame = cf
        hrp.AssemblyLinearVelocity = Vector3.zero
    end
end
local function walkFallback(targetPos, keepRot)
    local hrp = findHRP(plr.Character)
    if not hrp or not targetPos then return false end
    pcall(function() hrp.AssemblyLinearVelocity = Vector3.zero hrp.AssemblyAngularVelocity = Vector3.zero end)
    local function distLeft() return (Vector3.new(hrp.Position.X, 0, hrp.Position.Z) - Vector3.new(targetPos.X, 0, targetPos.Z)).Magnitude end
    if distLeft() < 1.2 then return true end
    while distLeft() > 1.2 do
        if not plr.Character or not hrp.Parent then return false end
        if not isDropVisible() then return false end
        local cur = Vector3.new(hrp.Position.X, targetPos.Y, hrp.Position.Z)
        local dir = Vector3.new(targetPos.X - cur.X, 0, targetPos.Z - cur.Z)
        if dir.Magnitude < 0.1 then break end
        dir = dir.Unit
        local dt = RunService.Heartbeat:Wait()
        local step = dir * getWalkSpeed() * dt
        if step.Magnitude > distLeft() then step = dir * distLeft() end
        local newPos = cur + step
        hrp.CFrame = keepRot and CFrame.new(newPos) * (hrp.CFrame - hrp.CFrame.Position) or CFrame.lookAt(newPos, newPos + dir)
        hrp.AssemblyLinearVelocity = Vector3.zero
    end
    return true
end
local function walkDefend(targetPos, mode)
    if mode == "None" or not mode then return walkFallback(targetPos, true) end
    local hrp = findHRP(plr.Character)
    if not hrp then return false end
    local start = Vector3.new(hrp.Position.X, targetPos.Y, hrp.Position.Z)
    local dir = targetPos - start
    local dist = Vector3.new(dir.X, 0, dir.Z).Magnitude
    if dist < 5 then return walkFallback(targetPos, true) end
    dir = Vector3.new(dir.X, 0, dir.Z).Unit
    local perp = Vector3.new(-dir.Z, 0, dir.X)
    local pts = {}
    if mode == "ZigZag" then for i = 1, 4 do local t = i / 5 table.insert(pts, start:Lerp(targetPos, t) + perp * ((i % 2 == 0 and 1 or -1) * 10)) end
    elseif mode == "Random" then for i = 1, 4 do local t = i / 5 table.insert(pts, start:Lerp(targetPos, t) + perp * math.random(-12, 12)) end
    elseif mode == "Circle" then for i = 1, 6 do local t = i / 7 local a = i * 60 table.insert(pts, start:Lerp(targetPos, t) + Vector3.new(math.cos(math.rad(a)) * 8, 0, math.sin(math.rad(a)) * 8)) end
    elseif mode == "Juke" then for i = 1, 5 do local t = i / 6 table.insert(pts, start:Lerp(targetPos, t) + perp * ((i % 2 == 0 and 14 or -14) + math.random(-4, 4))) end end
    for _, p in ipairs(pts) do if not walkFallback(p, true) then return false end task.wait(0.05) end
    return walkFallback(targetPos, true)
end
local function walkToSafeFallback()
    if not walkDefend(SAFE_BASE_MID, defendMode) then tpTo(SAFE_BASE_CF) return true end
    tpTo(SAFE_BASE_CF) task.wait(0.08) tpTo(SAFE_BASE_CF)
    return true
end
local function walkToSafe()
    if defendMode == "None" then tpTo(SAFE_BASE_CF) else walkDirect(SAFE_BASE_MID, nil, true) tpTo(SAFE_BASE_CF) end
end

-- ============ PROMPT SATUIN ============
local function makeBigPrompt(p)
    if not p:IsA("ProximityPrompt") then return end
    pcall(function() p.HoldDuration = 0 p.MaxActivationDistance = RANGE p.RequiresLineOfSight = false p.KeyboardKeyCode = Enum.KeyCode.E p.Exclusivity = Enum.ProximityPromptExclusivity.OnePerButton end)
end
local function firePrompt(p)
    if not p:IsA("ProximityPrompt") then return end
    makeBigPrompt(p)
    if fireproximityprompt then pcall(fireproximityprompt, p, 0) end
    pcall(function() p:InputHoldBegin() task.wait(0.05) p:InputHoldEnd() end)
end
local function anchorPosOf(pr)
    local p = pr.Parent
    if p:IsA("BasePart") then return p.Position end
    if p:IsA("Model") then if p.PrimaryPart then return p.PrimaryPart.Position end local ok, cf = pcall(function() return p:GetPivot() end) if ok then return Vector3.new(cf.X, cf.Y, cf.Z) end for _, b in ipairs(p:GetDescendants()) do if b:IsA("BasePart") then return b.Position end end end
    local bp = p:FindFirstChildWhichIsA("BasePart", true)
    if bp then return bp.Position end
    return nil
end
local function promptNear(m, md)
    local bp = posOf(m)
    if not bp then return nil end
    for _, v in ipairs(m:GetDescendants()) do if v:IsA("ProximityPrompt") then return v end end
    local best, mn = nil, md or 12
    for _, v in ipairs(workspace:GetDescendants()) do
        if v:IsA("ProximityPrompt") and v.Name:lower():find("steal") then
            local ap = anchorPosOf(v)
            if ap then local d = (Vector3.new(ap.X, 0, ap.Z) - Vector3.new(bp.X, 0, bp.Z)).Magnitude if d < mn then mn = d best = v end end
        end
    end
    return best
end
local function fireSteal(m)
    if not m or not m.Parent then return end
    for _, v in ipairs(m:GetDescendants()) do if v:IsA("ProximityPrompt") then firePrompt(v) end end
end
local function touchSteal(m)
    if not m or not m.Parent then return end
    local hrp = findHRP(plr.Character)
    local part = nil
    if m:IsA("BasePart") then part = m elseif m:IsA("Model") then part = m.PrimaryPart or m:FindFirstChildWhichIsA("BasePart") else part = m:FindFirstChildWhichIsA("BasePart", true) end
    if hrp and part then pcall(function() firetouchinterest(hrp, part, 0) task.wait(0.02) firetouchinterest(hrp, part, 1) end) end
end
local function pressE() pcall(function() VIM:SendKeyEvent(true, Enum.KeyCode.E, false, game) task.wait(0.05) VIM:SendKeyEvent(false, Enum.KeyCode.E, false, game) end) end
local function closestPlayerTo(m, maxDist)
    local pos = posOf(m)
    if not pos then return nil end
    local best, md = nil, maxDist or 20
    for _, p in ipairs(Players:GetPlayers()) do
        if p ~= plr and p.Character and findHRP(p.Character) then
            local hrp = findHRP(p.Character)
            local d = (Vector3.new(hrp.Position.X, 0, hrp.Position.Z) - Vector3.new(pos.X, 0, pos.Z)).Magnitude
            if d < md then md = d best = p end
        end
    end
    return best
end
local function equipBat()
    local char = plr.Character if not char then return nil end
    local bat = char:FindFirstChildWhichIsA("Tool")
    if bat and bat.Name:lower():find("bat") then return bat end
    for _, t in ipairs(plr.Backpack:GetChildren()) do if t:IsA("Tool") and t.Name:lower():find("bat") then t.Parent = char return t end end
    for _, t in ipairs(plr.Backpack:GetChildren()) do if t:IsA("Tool") then t.Parent = char return t end end
    return char:FindFirstChildOfClass("Tool")
end
local function attackCarrier(carrier)
    if not attackEnabled or not carrier or not carrier.Character then return end
    local hrp = findHRP(carrier.Character)
    if not hrp then return end
    for _ = 1, 20 do
        if not carrier.Character.Parent or not attackEnabled then break end
        local myHrp = findHRP(plr.Character)
        if not myHrp then break end
        local pred = hrp.Position + hrp.CFrame.LookVector * 5
        walkDirect(Vector3.new(pred.X, 3.5, pred.Z), hrp.Position, false)
        local bat = equipBat()
        if bat then pcall(function() bat:Activate() end) pcall(function() VIM:SendMouseButtonEvent(0, 0, 0, true, game, 0) task.wait(0.05) VIM:SendMouseButtonEvent(0, 0, 0, false, game, 0) end) end
        task.wait(0.15)
        if (Vector3.new(myHrp.Position.X, 0, myHrp.Position.Z) - Vector3.new(hrp.Position.X, 0, hrp.Position.Z)).Magnitude > 30 then break end
    end
end
local function notify(t, c) Window:Notify({ Title = t, Content = c, Duration = 2 }) end
local stealMode = "Normal"
local function stealMethod(m)
    if not m or not m.Parent then return end
    notify(m.Name, (m:GetAttribute("Rarity") or "Unknown") .. " - " .. cashTxt(m))
    local lastPos = posOf(m) local tries = 0
    while tries < 8 and m.Parent do
        if isDropVisible() then if not isCarryingTarget(m) then fireDropNow() task.wait(0.35) tries += 1 continue else break end end
        local curPos = posOf(m)
        if curPos and lastPos and (curPos - lastPos).Magnitude > 2 then local car = closestPlayerTo(m, 20) if car and attackEnabled then attackCarrier(car) end end
        lastPos = curPos local p, b = offsetPosOf(m) if p then walkDirect(p, b, false) end touchSteal(m) fireSteal(m) pressE() task.wait(0.25) tries += 1
        if isDropVisible() and not isCarryingTarget(m) then fireDropNow() task.wait(0.3) end
    end
    if not isDropVisible() then walkToSafe() return end
    if not isCarryingTarget(m) then fireDropNow() task.wait(0.3) return end
    if stealMode == "Helper" then if not walkDefend(HELPER_DROP_POS, defendMode) then return end if not isCarryingTarget(m) then fireDropNow() return end task.wait(0.15) fireDropNow() task.wait(0.2) walkToSafeFallback()
    else walkToSafeFallback() end
end

