local function espAdd(cache, model, color, title, sub, sub2)
    if not model or not model.Parent or cache[model] or not model:IsA("Model") then return end
    local ad = model.PrimaryPart or model:FindFirstChildWhichIsA("BasePart")
    if not ad then return end
    local hl = Instance.new("Highlight") hl.Name = "SoruEspHL" hl.Adornee = model hl.FillColor = color hl.OutlineColor = color hl.FillTransparency = 0.65 hl.OutlineTransparency = 0 hl.DepthMode = Enum.HighlightDepthMode.AlwaysOnTop hl.Parent = model
    local bb = Instance.new("BillboardGui") bb.Name = "SoruEspBB" bb.Adornee = ad bb.Size = UDim2.fromOffset(165, 56) bb.StudsOffset = Vector3.new(0, 4.2, 0) bb.AlwaysOnTop = true bb.Parent = ad
    local f = Instance.new("Frame", bb) f.Size = UDim2.new(1, 0, 1, 0) f.BackgroundColor3 = Color3.fromRGB(20, 18, 32) f.BackgroundTransparency = 0.12 Instance.new("UICorner", f).CornerRadius = UDim.new(0, 8)
    local st = Instance.new("UIStroke", f) st.Color = color st.Transparency = 0.2 st.Thickness = 1
    local n = Instance.new("TextLabel", f) n.Size = UDim2.new(1, -8, 0, 14) n.Position = UDim2.new(0, 5, 0, 4) n.BackgroundTransparency = 1 n.Text = title n.Font = Enum.Font.GothamBold n.TextSize = 10 n.TextColor3 = Color3.new(1, 1, 1) n.TextXAlignment = Enum.TextXAlignment.Left n.TextTruncate = Enum.TextTruncate.AtEnd
    local a = Instance.new("TextLabel", f) a.Size = UDim2.new(1, -8, 0, 11) a.Position = UDim2.new(0, 5, 0, 18) a.BackgroundTransparency = 1 a.Text = sub a.Font = Enum.Font.GothamMedium a.TextSize = 9 a.TextColor3 = color a.TextXAlignment = Enum.TextXAlignment.Left
    local b = Instance.new("TextLabel", f) b.Size = UDim2.new(1, -8, 0, 10) b.Position = UDim2.new(0, 5, 0, 30) b.BackgroundTransparency = 1 b.Text = sub2 b.Font = Enum.Font.GothamMedium b.TextSize = 8 b.TextColor3 = DIM b.TextXAlignment = Enum.TextXAlignment.Left
    cache[model] = { hl = hl, bb = bb }
end
local function espDel(cache, model)
    local d = cache[model]
    if d then pcall(function() if d.hl then d.hl:Destroy() end end) pcall(function() if d.bb then d.bb:Destroy() end end) cache[model] = nil end
end
local function espClear(cache) for m, _ in pairs(cache) do espDel(cache, m) end table.clear(cache) end
local function createAnimalEsp(m)
    local r = m:GetAttribute("Rarity") or "Unknown"
    if next(selectedEspRarity) ~= nil and not selectedEspRarity[r] then return end
    local w = m:GetAttribute("WeightKg") or m:GetAttribute("Weight") or 0
    espAdd(espCache, m, rarityColor(r), m.Name:upper(), string.upper(r) .. " • " .. cashTxt(m), tostring(w) .. " KG • " .. zoneOf(m))
end
local function refreshAnimalEsp()
    if not espEnabled then espClear(espCache) return end
    local folder = workspace:FindFirstChild("AnimalPickups")
    if not folder then return end
    for _, m in ipairs(folder:GetChildren()) do if m:IsA("Model") then local r = m:GetAttribute("Rarity") or "Unknown" if next(selectedEspRarity) == nil or selectedEspRarity[r] then createAnimalEsp(m) else espDel(espCache, m) end end end
    for m, _ in pairs(espCache) do if not m.Parent then espDel(espCache, m) end end
end

-- ============ EGG ============
local function eggSize(m)
    for _, a in ipairs({ "Size", "EggSize", "Scale", "WeightKg", "Weight", "SizeMultiplier" }) do local v = m:GetAttribute(a) if typeof(v) == "number" then return v end end
    for _, d in ipairs(m:GetDescendants()) do if d:IsA("NumberValue") and d.Name:lower():find("size") then return d.Value end end
    local ok, _, sz = pcall(function() return m:GetBoundingBox() end)
    if ok and sz then return sz.Magnitude end
    return 0
end
local function eggCat(m)
    local s = eggSize(m)
    if s < 8 then return "Small" elseif s < 16 then return "Standar" elseif s < 28 then return "Big" else return "Titan" end
end
local function eggsInZone(zoneName)
    local zb = zoneFolder()
    if not zb then return {} end
    local zm = zb:FindFirstChild(zoneName)
    if not zm then return {} end
    local root = zm:FindFirstChild("Eggs") or zm
    local out = {}
    for _, v in ipairs(root:GetChildren()) do if v:IsA("Model") and v.Name:lower():find("egg") then table.insert(out, v) end end
    if #out == 0 then for _, v in ipairs(root:GetDescendants()) do if v:IsA("Model") and v.Name:lower():find("egg") then table.insert(out, v) end end end
    if bigEggPriority then table.sort(out, function(a, b) return eggSize(a) > eggSize(b) end) end
    return out
end
local function allEggs()
    local zb = zoneFolder()
    if not zb then return {} end
    local out = {}
    for _, z in ipairs(zb:GetChildren()) do if z:IsA("Model") then for _, e in ipairs(eggsInZone(z.Name)) do table.insert(out, e) end end end
    return out
end
local function zoneTeleportPos(zoneName)
    local eggs = eggsInZone(zoneName)
    if #eggs > 0 then local p = posOf(eggs[1]) if p then return Vector3.new(p.X, 5, p.Z) end end
    local zb = zoneFolder()
    if zb then local zm = zb:FindFirstChild(zoneName) if zm then local p = posOf(zm) if p then return Vector3.new(p.X, 5, p.Z) end end end
    return nil
end
local function createEggEsp(m)
    if next(selectedEggZones) ~= nil and not selectedEggZones[zoneOf(m)] then return end
    local cat = eggCat(m)
    if next(selectedEggSizes) ~= nil and not selectedEggSizes[cat] then return end
    local col = cat == "Titan" and Color3.fromRGB(255, 60, 60) or cat == "Big" and Color3.fromRGB(255, 180, 0) or cat == "Standar" and Color3.fromRGB(85, 170, 255) or Color3.fromRGB(180, 180, 180)
    espAdd(eggEspCache, m, col, m.Name:upper(), cat .. " • " .. zoneOf(m), "")
end
local function refreshEggEsp()
    if not eggEspEnabled then espClear(eggEspCache) return end
    for _, m in ipairs(allEggs()) do createEggEsp(m) end
    for m, _ in pairs(eggEspCache) do if not m.Parent then espDel(eggEspCache, m) end end
end

