local zoneNames = namesFrom(zoneFolder())
local defendModes = { "None", "ZigZag", "Random", "Circle", "Juke" }
local selected, selectedZones, selectedEggZone = {}, {}, nil
local function stealTargets()
    local folder = workspace:FindFirstChild("AnimalPickups")
    if not folder or next(selected) == nil then return {} end
    local out = {}
    for _, m in ipairs(folder:GetChildren()) do
        if m:IsA("Model") and selected[m:GetAttribute("Rarity")] then
            if next(selectedZones) ~= nil and not selectedZones[zoneOf(m)] then continue end
            if minCashFilter > 0 and parseCash(cashTxt(m)) < minCashFilter then continue end
            table.insert(out, m)
        end
    end
    table.sort(out, function(a, b) return rarityScore(a:GetAttribute("Rarity") or "") > rarityScore(b:GetAttribute("Rarity") or "") end)
    return out
end
local function eggHealth(e)
    if e:GetAttribute("Health") then return e:GetAttribute("Health") end
    for _, d in ipairs(e:GetDescendants()) do local h = d:GetAttribute("Health") if h ~= nil then return h end end
