local function equipPickaxe()
    local char = plr.Character if not char then return nil end
    local tool = char:FindFirstChildOfClass("Tool")
    if tool and tool.Name:lower():find("pickaxe") then return tool end
    for _, t in ipairs(plr.Backpack:GetChildren()) do if t:IsA("Tool") and t.Name:lower():find("pickaxe") then t.Parent = char return t end end
    for _, t in ipairs(plr.Backpack:GetChildren()) do if t:IsA("Tool") then t.Parent = char return t end end
    return char:FindFirstChildOfClass("Tool")
end

-- ============ TRACKER ============
local function instantSteal(m)
    if not m or not m.Parent then return end
    local hrp = findHRP(plr.Character)
    if not hrp then return end
    local st = tick()
    while tick() - st < 0.4 do
        if not m.Parent then break end
        local pr = promptNear(m, 12)
        if pr then local an = anchorPosOf(pr) local bs = posOf(m) if an and bs and (Vector3.new(an.X, 0, an.Z) - Vector3.new(bs.X, 0, bs.Z)).Magnitude <= 12 then hrp.CFrame = CFrame.new(an + Vector3.new(0, 0.5, 0)) firePrompt(pr) touchSteal(m) end end
        if isDropVisible() then break end
        task.wait(0.01)
    end
    tpTo(SAFE_BASE_CF) task.wait(0.05) tpTo(SAFE_BASE_CF)
end
local function legitSteal(m)
    if not m or not m.Parent then return end
    local tries = 0
    while tries < 8 and m.Parent do
        if isDropVisible() then if isCarryingTarget(m) then break end fireDropNow() task.wait(0.35) tries += 1 continue end
        local p, b = offsetPosOf(m)
        if not p then local bp = posOf(m) if bp then p = Vector3.new(bp.X, 3.5, bp.Z + 3) b = Vector3.new(bp.X, 3.5, bp.Z) end end
        if p then walkDirect(p, b, false) end
        touchSteal(m) fireSteal(m) pressE() task.wait(0.25) tries += 1
    end
    if isCarryingTarget(m) then walkToSafeFallback() end
end
local function sortedAnimals()
    local folder = workspace:FindFirstChild("AnimalPickups")
    if not folder then return {} end
    local list = {}
    for _, m in ipairs(folder:GetChildren()) do
        if m:IsA("Model") then local txt = cashTxt(m) local cv = parseCash(txt) if cv == 0 then local at = m:GetAttribute("CashPerSecond") or m:GetAttribute("CPS") if typeof(at) == "number" then cv = at txt = "$" .. tostring(at) .. "/s" elseif typeof(at) == "string" then cv = parseCash(at) txt = at end end table.insert(list, { model = m, cash = cv, txt = txt }) end
    end
    table.sort(list, function(a, b) return a.cash > b.cash end)
    return list
end
local function stealByRank(i)
    local list = sortedAnimals()
    local m = list[i] and list[i].model or nil
    if not m then return end
    task.spawn(function() pcall(function() if trackerMode == "Blatant" then instantSteal(m) else legitSteal(m) end end) end)
end

-- ============ DIAMOND DIRECT ============
local diamondZone, diamondFarmSpeed, diamondOn, diamondTween = nil, 60, false, nil
local function hasGem()
    local d = workspace:FindFirstChild("EggGemDrops")
    return d ~= nil and #d:GetChildren() > 0
end
local function eggTimeLeft(e)
    for _, n in ipairs({ "TimeLeft", "Time", "Remaining", "RemainingTime", "Timer", "HatchTime", "HatchIn", "Duration", "Countdown", "TimeRemaining" }) do local v = e:GetAttribute(n) if typeof(v) == "number" then return v end end
    for _, d in ipairs(e:GetDescendants()) do if (d:IsA("NumberValue") or d:IsA("IntValue")) and (d.Name:lower():find("time") or d.Name:lower():find("timer") or d.Name:lower():find("left") or d.Name:lower():find("remain")) then return d.Value end end
    return nil
end
local function tweenTo(pos, speed)
    local hrp = findHRP(plr.Character)
    if not hrp or not pos then return end
    if diamondTween then pcall(function() diamondTween:Cancel() end) end
    local dist = (Vector3.new(hrp.Position.X, 0, hrp.Position.Z) - Vector3.new(pos.X, 0, pos.Z)).Magnitude
    local dur = math.max(dist / math.max(speed, 1), 0.15)
    diamondTween = TweenService:Create(hrp, TweenInfo.new(dur, Enum.EasingStyle.Linear), { CFrame = CFrame.new(Vector3.new(pos.X, pos.Y, pos.Z)) })
    diamondTween:Play()
    diamondTween.Completed:Wait()
end
local function collectGems()
    local drops = workspace:FindFirstChild("EggGemDrops")
    if not drops then return end
    while diamondOn and drops.Parent and #drops:GetChildren() > 0 do
        for _, child in ipairs(drops:GetChildren()) do
            if not diamondOn then return end
            if not child.Parent then continue end
            local pos = child:IsA("BasePart") and child.Position or posOf(child)
            if not pos then continue end
            pcall(function() tweenTo(Vector3.new(pos.X, pos.Y + 1, pos.Z), diamondFarmSpeed) end)
            task.wait(0.1)
            local hrp = findHRP(plr.Character)
            local part = child:IsA("BasePart") and child or (child:IsA("Model") and (child.PrimaryPart or child:FindFirstChildWhichIsA("BasePart")) or nil)
            if hrp and part then pcall(function() firetouchinterest(hrp, part, 0) task.wait(0.05) firetouchinterest(hrp, part, 1) end) end
        end
        task.wait(0.1)
    end
end
local function diamondLoop()
    while diamondOn do
        if hasGem() then collectGems()
        else
            if not diamondZone then task.wait(0.5) continue end
            local eggs = eggsInZone(diamondZone)
            if #eggs == 0 then task.wait(1) continue end
            for _, egg in ipairs(eggs) do
                if not diamondOn then break end
                if hasGem() then break end
                local pos, base = offsetPosOf(egg)
                if not pos then continue end
                pcall(function()
                    walkDirect(pos, base, false)
                    equipPickaxe()
                    while diamondOn and egg.Parent do
                        if hasGem() then break end
                        local h = eggHealth(egg)
                        if h ~= nil and h <= 0 then break end
                        local t = eggTimeLeft(egg)
                        if t ~= nil and t <= 0 then break end
                        task.wait(0.15)
                    end
                end)
            end
        end
        task.wait(0.2)
    end
end

-- ============ ANTI RAGDOLL AUTO DETECT Y+2 ============
local autoRagdollOn, ragdollConn, lastY, lastSafeCF, protecting = false, nil, 0, nil, false
local function stopRagdoll()
    if ragdollConn then pcall(function() ragdollConn:Disconnect() end) ragdollConn = nil end
    protecting = false lastSafeCF = nil
    local hum = findHumanoid(plr.Character)
    if hum then pcall(function() hum:SetStateEnabled(Enum.HumanoidStateType.Ragdoll, true) hum:SetStateEnabled(Enum.HumanoidStateType.FallingDown, true) hum:SetStateEnabled(Enum.HumanoidStateType.Physics, true) hum.PlatformStand = false end) end
end
local function startRagdoll()
    stopRagdoll()
    local hrp = findHRP(plr.Character)
    if hrp then lastY = hrp.Position.Y lastSafeCF = hrp.CFrame end
    ragdollConn = RunService.Heartbeat:Connect(function()
        if not autoRagdollOn then return end
        local hum = findHumanoid(plr.Character)
        local r = findHRP(plr.Character)
        if not hum or not r then return end
        local curY = r.Position.Y
        local deltaY = curY - lastY
        local velY = r.AssemblyLinearVelocity.Y
        if not protecting and hum.FloorMaterial ~= Enum.Material.Air and velY < 5 and math.abs(deltaY) < 0.5 then lastSafeCF = r.CFrame lastY = curY return end
        if not protecting and deltaY >= 2 then
            protecting = true
            if lastSafeCF then r.CFrame = CFrame.new(lastSafeCF.Position + Vector3.new(0, 0.5, 0)) * (lastSafeCF - lastSafeCF.Position) else r.CFrame = CFrame.new(r.Position.X, lastY, r.Position.Z) end
            r.AssemblyLinearVelocity = Vector3.zero r.AssemblyAngularVelocity = Vector3.zero r.Velocity = Vector3.zero
            hum.PlatformStand = false hum:ChangeState(Enum.HumanoidStateType.RunningNoPhysics) task.wait() hum:ChangeState(Enum.HumanoidStateType.Running)
            hum:SetStateEnabled(Enum.HumanoidStateType.Ragdoll, false) hum:SetStateEnabled(Enum.HumanoidStateType.FallingDown, false) hum:SetStateEnabled(Enum.HumanoidStateType.Physics, false)
            task.delay(0.8, function()
                if hum.Parent then hum:SetStateEnabled(Enum.HumanoidStateType.Ragdoll, true) hum:SetStateEnabled(Enum.HumanoidStateType.FallingDown, true) hum:SetStateEnabled(Enum.HumanoidStateType.Physics, true) end
                protecting = false
                local rr = findHRP(plr.Character)
                if rr then lastY = rr.Position.Y lastSafeCF = rr.CFrame end
            end)
            return
        end
        if protecting and (hum:GetState() == Enum.HumanoidStateType.Ragdoll or hum:GetState() == Enum.HumanoidStateType.FallingDown or hum.PlatformStand) then hum.PlatformStand = false hum:ChangeState(Enum.HumanoidStateType.Running) end
        if not protecting and deltaY < 2 then lastY = curY end
    end)
end

